import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"CSV-Export","description":"Daten aus einer Ansicht als CSV-Datei herunterladen.","frontmatter":{"title":"CSV-Export","description":"Daten aus einer Ansicht als CSV-Datei herunterladen."},"headers":[],"relativePath":"grids/csv-export.md","filePath":"grids/csv-export.md","lastUpdated":1788108473000}'),a={name:"grids/csv-export.md"};function s(l,e,o,d,c,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="csv-export" tabindex="-1">CSV-Export <a class="header-anchor" href="#csv-export" aria-label="Permalink to &quot;CSV-Export&quot;">​</a></h1><p>Über <strong>Weitere</strong> (⋮) → <strong>Als CSV exportieren</strong> laden Sie die Daten einer Ansicht als Tabellendatei herunter.</p><h2 id="was-exportiert-wird" tabindex="-1">Was exportiert wird <a class="header-anchor" href="#was-exportiert-wird" aria-label="Permalink to &quot;Was exportiert wird&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Der Export folgt der Ansicht, nicht dem Grid</p><p>Exportiert wird genau das, was in der aktuellen <strong>Ansicht</strong> sichtbar ist:</p><ul><li>nur die Einträge, die der <strong>Filter</strong> durchlässt</li><li>nur die <strong>eingeblendeten</strong> Spalten</li><li>in der eingestellten <strong>Reihenfolge</strong> von Spalten und Sortierung</li></ul><p>Wollen Sie alles, wechseln Sie vorher in eine ungefilterte Ansicht mit allen Spalten.</p></div><div class="tip custom-block"><p class="custom-block-title">Eine Ansicht speziell für den Export</p><p>Wenn Sie regelmäßig exportieren, lohnt sich eine eigene Ansicht: genau die benötigten Spalten, in der Reihenfolge, die das Zielsystem erwartet, mit passendem Filter. Dann ist der Export ein Klick statt jedes Mal Umbauen.</p></div><h2 id="wofur-der-export-nutzlich-ist" tabindex="-1">Wofür der Export nützlich ist <a class="header-anchor" href="#wofur-der-export-nutzlich-ist" aria-label="Permalink to &quot;Wofür der Export nützlich ist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zweck</th><th>Hinweis</th></tr></thead><tbody><tr><td><strong>Sicherung vor riskanten Änderungen</strong></td><td>Vor Typänderungen und Massenlöschungen</td></tr><tr><td><strong>Auswertung in einer Tabellenkalkulation</strong></td><td>Für Ad-hoc-Auswertungen und Pivot-Tabellen</td></tr><tr><td><strong>Übergabe an ein anderes System</strong></td><td>Buchhaltung, Serienbrief, Statistik</td></tr><tr><td><strong>Umzug in ein anderes Grid</strong></td><td>Export, dann <a href="/grids/csv-import">CSV-Import</a></td></tr></tbody></table><h2 id="grenzen" tabindex="-1">Grenzen <a class="header-anchor" href="#grenzen" aria-label="Permalink to &quot;Grenzen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Was der Export nicht mitnimmt</p><ul><li><strong>Dateianhänge</strong> — nur Verweise oder Namen, nicht die Dateien selbst</li><li><strong>Verknüpfungen</strong> — als Anzeigetext, nicht als Verweis. Beim Reimport entsteht daraus keine Verknüpfung.</li><li><strong>Berechnete Felder</strong> — als berechneter Wert, nicht als Berechnungsvorschrift</li><li><strong>Ausgeblendete Spalten</strong> — gar nicht</li><li><strong>Aufbau</strong> — Ansichten, Formulare, Flows und Seiten lassen sich nicht exportieren</li></ul></div><p>Für einen vollständigen Umzug ist ein CSV-Export deshalb <strong>keine Sicherung des Aufbaus</strong>. Er sichert die Daten, nicht die Anwendung.</p><h2 id="umlaute-und-excel" tabindex="-1">Umlaute und Excel <a class="header-anchor" href="#umlaute-und-excel" aria-label="Permalink to &quot;Umlaute und Excel&quot;">​</a></h2><p>Die exportierte Datei ist UTF-8-kodiert.</p><div class="tip custom-block"><p class="custom-block-title">Wenn Excel Umlaute zerstört</p><p>Ein Doppelklick auf die CSV-Datei öffnet sie in manchen Excel-Versionen mit falscher Kodierung — aus <code>Müller</code> wird <code>MÃ¼ller</code>.</p><p>Der zuverlässige Weg: In Excel <em>Daten → Aus Text/CSV</em>, dort <strong>UTF-8</strong> als Dateiursprung wählen. In LibreOffice Calc erscheint der Import-Dialog automatisch.</p><p>Der Export selbst ist in Ordnung — es ist ein Öffnungsproblem.</p></div><h2 id="berechtigung" tabindex="-1">Berechtigung <a class="header-anchor" href="#berechtigung" aria-label="Permalink to &quot;Berechtigung&quot;">​</a></h2><p>Der Export erfordert entsprechende Rechte. Fehlt der Menüpunkt, prüfen Sie Ihre <a href="/zusammenarbeit/rollen">Rolle</a>.</p><p>In veröffentlichten <a href="/seiten/portal-veroeffentlichen">Portalen</a> steuern Sie über die Blockeinstellung <strong>CSV-Download anzeigen</strong>, ob Besucher exportieren dürfen.</p><div class="warning custom-block"><p class="custom-block-title">Export in Portalen bewusst freigeben</p><p>Ist <em>CSV-Download anzeigen</em> aktiv, können Besucher den gesamten sichtbaren Datenbestand herunterladen — nicht nur ansehen. Für Portale mit personenbezogenen Daten sollten Sie das ausgeschaltet lassen.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/csv-import">CSV-Import</a></li><li><a href="/ansichten/spalten-verwalten">Spalten verwalten</a></li><li><a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li></ul>',19)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
